        new_id = max([struct.unpack_from("<I", e.key)[0] for e in entries] + [0x100]) + 1
        used_end = 0
        for e in entries:
            _hh, _i, offset, length = struct.unpack_from("<IIQI", e.data)
            used_end = max(used_end, offset + length)
